package com.rescue.common;

public class Result<T> {
    private int code;
    private String msg;
    private T data;

    public Result() {}
    public Result(int code, String msg, T data) {
        this.code = code; this.msg = msg; this.data = data;
    }

    public static <T> Result<T> ok() { return new Result<>(200, "success", null); }
